-- gold: the Weekly Dashboard scorecard - pillars, measures, bands, settings, and the
-- inspection / meeting classifiers.
--
-- GENERATED by _local/make_qc_seeds.py from 02-transformation/seed/dashboard_*.csv. Do
-- not edit by hand. Weights are the Oct 21 call's (schedule 50, budget 30, safety 15,
-- quality 5); measures and bands are Scorecard.xlsx's, column H. Rows whose Source says
-- PROPOSED are not in the workbook and wait on Affect. Retuning the scorecard is a CSV
-- edit and a regenerate, never a DAX change.

-- dim_DashPillar: 5 row(s) from seed/dashboard_pillar.csv
CREATE OR REPLACE TABLE dim_DashPillar AS
SELECT CAST(c1 AS INT) AS PillarKey,
       CAST(c2 AS STRING) AS Pillar,
       CAST(c3 AS DOUBLE) AS Weight,
       CAST(c4 AS INT) AS SortOrder,
       CAST(c5 AS STRING) AS ScorecardDepartment,
       CAST(c6 AS STRING) AS Source
FROM (VALUES
    ('1', 'Schedule', '0.50', '1', 'Field Ops', 'Oct 21 call: schedule 50%, budget 30%, safety 15%, quality 5% initially'),
    ('2', 'Budget', '0.30', '2', 'Financial', 'Oct 21 call: schedule 50%, budget 30%, safety 15%, quality 5% initially'),
    ('3', 'Safety', '0.15', '3', 'Safety', 'Oct 21 call: schedule 50%, budget 30%, safety 15%, quality 5% initially'),
    ('4', 'Quality', '0.05', '4', 'Quality', 'Oct 21 call: schedule 50%, budget 30%, safety 15%, quality 5% initially'),
    ('5', 'Risk', '0.00', '5', 'Risk', 'Scorecard.xlsx: insurance coming soon; no weight until it is measured')
) AS t(c1, c2, c3, c4, c5, c6);

-- dim_DashMetric: 17 row(s) from seed/dashboard_metric.csv
