-- dim_DashSetting: 13 row(s) from seed/dashboard_setting.csv
CREATE OR REPLACE TABLE dim_DashSetting AS
SELECT CAST(c1 AS STRING) AS SettingKey,
       CAST(c2 AS DOUBLE) AS Value,
       CAST(c3 AS STRING) AS Note
FROM (VALUES
    ('gross_margin_target', '0.125', 'Oct 21 call: 12.5% now, 13% from the end of Q1'),
    ('phase_precon_below', '0.10', 'Billed % below this = Precon (deck slide 2)'),
    ('phase_closeout_from', '0.95', 'Billed % above this = Closeout (deck slide 2)'),
    ('archive_paid_from', '0.995', 'Collected / contract at or above this = archived (Oct 21 call: once 100% paid)'),
    ('grade_on_track_from', '90', 'PROPOSED: grade at or above = On track (deck: 100 On track)'),
    ('grade_monitor_from', '75', 'Deck slide 2: 75 Monitor, below 75 Needs attention'),
    ('grade_at_risk_max', '45', 'Oct 21 call: at-risk projects are grades 45 and below'),
    ('min_coverage', '0.5', 'A grade needs at least this share of the weight measured'),
    ('risk_metric_below', '0.80', 'Oct 21 call: a measure scoring below 80% is listed as a top risk'),
    ('risk_high_below', '0.50', 'PROPOSED: a top risk is High below this score, Medium otherwise'),
    ('lookahead_days', '21', 'Deck slide 3: near-term milestones and critical path, next 3 weeks'),
    ('ar_aged_days', '60', 'Deck slide 1: AR > 60 days'),
    ('active_within_days', '60', 'PROPOSED: Active = any Procore activity (daily log, meeting, inspection, RFI, submittal, observation) within this many days')
) AS t(c1, c2, c3);

